    --color-secondary-hover: var(--surface-container-highest, #42444d);
    --color-accent: var(--surface-container-highest, #42444d);
    --color-accent-foreground: var(--on-surface-default, #e6e8f0);
    --color-muted: var(--surface-container, #2c2e35);
    --color-muted-foreground: var(--on-surface-de-emphasis, #adafb8);
